#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <array>
#include <cerrno>
#include <cstdint>
#include <format>
#include <iostream>
#include <string>
#include <string_view>
#include <utility>

// Owns one file descriptor and closes it. A socket is a resource like any other, and the only
// reason so much socket code leaks one is that the C interface hands back a bare int.
class Socket {
 public:
  explicit Socket(int domain, int type) : fd_(::socket(domain, type, 0)) {}
  Socket(const Socket&) = delete;
  Socket& operator=(const Socket&) = delete;
  Socket(Socket&& other) noexcept : fd_(std::exchange(other.fd_, -1)) {}
  Socket& operator=(Socket&& other) noexcept {
    std::swap(fd_, other.fd_);
    return *this;
  }
  ~Socket() {
    if (fd_ >= 0) ::close(fd_);
  }

  [[nodiscard]] int get() const { return fd_; }
  [[nodiscard]] bool valid() const { return fd_ >= 0; }

 private:
  int fd_ = -1;
};

[[nodiscard]] sockaddr_in loopback(std::uint16_t port) {
  sockaddr_in address{};
  address.sin_family = AF_INET;
  address.sin_port = htons(port);
  address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
  return address;
}

// Asks the kernel which port it gave us. Binding to port 0 means "any free one", which is what a
// test wants: a fixed port is a test that fails when somebody else is already using it.
[[nodiscard]] std::uint16_t port_of(const Socket& socket) {
  sockaddr_in address{};
  socklen_t length = sizeof(address);
  if (::getsockname(socket.get(), reinterpret_cast<sockaddr*>(&address), &length) != 0) return 0;
  return ntohs(address.sin_port);
}

int main() {
  Socket server(AF_INET, SOCK_DGRAM);
  Socket client(AF_INET, SOCK_DGRAM);
  if (!server.valid() || !client.valid()) {
    std::cout << "could not open a socket\n";
    return 1;
  }

  const sockaddr_in any_port = loopback(0);
  if (::bind(server.get(), reinterpret_cast<const sockaddr*>(&any_port), sizeof(any_port)) != 0) {
    std::cout << "could not bind\n";
    return 1;
  }
  const sockaddr_in server_address = loopback(port_of(server));

  // SO_RCVTIMEO is what gives up rather than waiting for ever. Without it the next line has no
  // timeout at all, which is the worst kind of failure: a hang with nothing in any log.
  timeval limit{};
  limit.tv_usec = 200000;  // 200 ms
  ::setsockopt(client.get(), SOL_SOCKET, SO_RCVTIMEO, &limit, sizeof(limit));
  ::setsockopt(server.get(), SOL_SOCKET, SO_RCVTIMEO, &limit, sizeof(limit));

  std::array<char, 256> buffer{};
  for (const std::string_view request : {"odom 1", "odom 2", "scan"}) {
    ::sendto(client.get(), request.data(), request.size(), 0,
             reinterpret_cast<const sockaddr*>(&server_address), sizeof(server_address));

    sockaddr_in from{};
    socklen_t from_length = sizeof(from);
    const auto taken = ::recvfrom(server.get(), buffer.data(), buffer.size(), 0,
                                  reinterpret_cast<sockaddr*>(&from), &from_length);
    if (taken < 0) {
      std::cout << "the server heard nothing\n";
      return 1;
    }
    ::sendto(server.get(), buffer.data(), static_cast<std::size_t>(taken), 0,
             reinterpret_cast<const sockaddr*>(&from), from_length);

    const auto echoed = ::recvfrom(client.get(), buffer.data(), buffer.size(), 0, nullptr, nullptr);
    if (echoed < 0) {
      std::cout << "the client heard nothing\n";
      return 1;
    }
    const std::string_view reply(buffer.data(), static_cast<std::size_t>(echoed));
    std::cout << std::format("sent '{}', got back '{}', {} bytes\n", request, reply, echoed);
  }

  // Nobody is going to answer this one, so the timeout is what ends the call.
  errno = 0;
  const auto nothing = ::recvfrom(client.get(), buffer.data(), buffer.size(), 0, nullptr, nullptr);
  const bool timed_out = nothing < 0 && (errno == EAGAIN || errno == EWOULDBLOCK);
  std::cout << std::format("with no reply to wait for: {}\n", timed_out ? "timed out after 200 ms" : "something else");
}
